// src/utils/themeDetection.js

const THEME_STORAGE_KEY = 'user-theme-preference';
const DARK_THEME = 'dark';
const LIGHT_THEME = 'light';

/**
 * Detects the user's preferred color scheme from the system settings.
 * Returns 'dark' or 'light'.
 */
function detectSystemTheme() {
  if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') {
    // Default to light if no window or matchMedia support
    return LIGHT_THEME;
  }
  const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
  return prefersDark ? DARK_THEME : LIGHT_THEME;
}

/**
 * Retrieves the stored user theme preference from localStorage.
 * Returns 'dark', 'light', or null if no preference stored.
 */
function getStoredTheme() {
  if (typeof window === 'undefined' || typeof window.localStorage === 'undefined') {
    return null;
  }
  try {
    const stored = window.localStorage.getItem(THEME_STORAGE_KEY);
    if (stored === DARK_THEME || stored === LIGHT_THEME) {
      return stored;
    }
    return null;
  } catch {
    return null;
  }
}

/**
 * Stores the user theme preference in localStorage.
 * Accepts 'dark' or 'light'.
 */
function storeTheme(theme) {
  if (typeof window === 'undefined' || typeof window.localStorage === 'undefined') {
    return;
  }
  if (theme !== DARK_THEME && theme !== LIGHT_THEME) {
    throw new Error(`Invalid theme value: ${theme}`);
  }
  try {
    window.localStorage.setItem(THEME_STORAGE_KEY, theme);
  } catch {
    // Fail silently if storage is not available
  }
}

/**
 * Gets the effective theme for the user.
 * Priority:
 * 1. Stored user preference
 * 2. System preference
 */
function getEffectiveTheme() {
  const stored = getStoredTheme();
  if (stored) {
    return stored;
  }
  return detectSystemTheme();
}

/**
 * Applies the theme to the document root element by setting a data attribute.
 * @param {string} theme - 'dark' or 'light'
 */
function applyTheme(theme) {
  if (typeof document === 'undefined' || !document.documentElement) {
    return;
  }
  if (theme !== DARK_THEME && theme !== LIGHT_THEME) {
    throw new Error(`Invalid theme value: ${theme}`);
  }
  document.documentElement.setAttribute('data-theme', theme);
}

/**
 * Initializes theme on first visit or page load.
 * Applies the effective theme and persists it if no stored preference.
 */
function initTheme() {
  const stored = getStoredTheme();
  if (stored) {
    applyTheme(stored);
  } else {
    const systemTheme = detectSystemTheme();
    applyTheme(systemTheme);
    // Persist the detected system theme as initial preference
    storeTheme(systemTheme);
  }
}

export {
  DARK_THEME,
  LIGHT_THEME,
  detectSystemTheme,
  getStoredTheme,
  storeTheme,
  getEffectiveTheme,
  applyTheme,
  initTheme,
};

