// src/utils/persistence.js

const THEME_KEY = 'user-theme-preference';

/**
 * Detects the user's preferred color scheme using the system setting.
 * Returns 'dark' or 'light'.
 */
export function detectSystemTheme() {
  if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') {
    // Default to light if no window or matchMedia support
    return 'light';
  }
  return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
}

/**
 * Retrieves the stored user theme preference from localStorage.
 * Returns 'dark', 'light', or null if no preference is stored.
 */
export function getStoredTheme() {
  if (typeof window === 'undefined' || typeof window.localStorage === 'undefined') {
    return null;
  }
  try {
    const stored = window.localStorage.getItem(THEME_KEY);
    if (stored === 'dark' || stored === 'light') {
      return stored;
    }
    return null;
  } catch {
    return null;
  }
}

/**
 * Stores the user's theme preference in localStorage.
 * Accepts 'dark' or 'light'. Passing null removes the stored preference.
 */
export function storeTheme(theme) {
  if (typeof window === 'undefined' || typeof window.localStorage === 'undefined') {
    return;
  }
  try {
    if (theme === 'dark' || theme === 'light') {
      window.localStorage.setItem(THEME_KEY, theme);
    } else {
      window.localStorage.removeItem(THEME_KEY);
    }
  } catch {
    // Fail silently
  }
}

/**
 * Returns the effective theme to use:
 * - If user has stored preference, use it.
 * - Otherwise, detect system preference.
 */
export function getEffectiveTheme() {
  const stored = getStoredTheme();
  if (stored) {
    return stored;
  }
  return detectSystemTheme();
}

