import React, { useContext, useMemo } from 'react';

// Theme context to provide current theme ('light' or 'dark')
const ThemeContext = React.createContext('light');

// Basic syntax highlighting rules for a SQL-like query language
const syntaxRules = [
  {
    // Keywords
    regex: /\b(SELECT|FROM|WHERE|AND|OR|INSERT|INTO|VALUES|UPDATE|SET|DELETE|JOIN|ON|AS|ORDER BY|GROUP BY|LIMIT|OFFSET|INNER|LEFT|RIGHT|FULL|OUTER|DISTINCT|CREATE|TABLE|DROP|ALTER|ADD|COLUMN|INDEX|VIEW|TRIGGER|PROCEDURE|FUNCTION|RETURN|BEGIN|END|IF|ELSE|ELSEIF|CASE|WHEN|THEN)\b/gi,
    className: 'keyword',
  },
  {
    // Strings
    regex: /'([^'\\]*(\\.[^'\\]*)*)'/g,
    className: 'string',
  },
  {
    // Numbers
    regex: /\b\d+(\.\d+)?\b/g,
    className: 'number',
  },
  {
    // Comments -- single line
    regex: /--.*/g,
    className: 'comment',
  },
  {
    // Comments -- multi line
    regex: /\/\*[\s\S]*?\*\//g,
    className: 'comment',
  },
  {
    // Operators
    regex: /\b(=|<>|!=|<|>|<=|>=|\+|-|\*|\/|%|&&|\|\|)\b/g,
    className: 'operator',
  },
  {
    // Identifiers (table/column names) - simple heuristic: words not matched by keywords
    regex: /\b[a-zA-Z_][a-zA-Z0-9_]*\b/g,
    className: 'identifier',
  },
];

// Helper to escape HTML special characters
function escapeHtml(text) {
  return text.replace(/&/g, '&amp;')
             .replace(/</g, '&lt;')
             .replace(/>/g, '&gt;');
}

// Apply syntax highlighting by wrapping matched tokens with spans and classes
function applySyntaxHighlighting(text) {
  // We'll process the text by splitting into tokens and wrapping matches.
  // To handle overlapping matches, we process in order of rules and keep track of indices.

  const tokens = [];
  let lastIndex = 0;
  const textLength = text.length;

  // Collect all matches from all rules
  const matches = [];

  syntaxRules.forEach(({ regex, className }) => {
    let match;
    // Reset regex lastIndex for global regexes
    regex.lastIndex = 0;
    while ((match = regex.exec(text)) !== null) {
      matches.push({
        start: match.index,
        end: match.index + match[0].length,
        className,
        text: match[0],
      });
      // Avoid infinite loops for zero-length matches
      if (match.index === regex.lastIndex) {
        regex.lastIndex++;
      }
    }
  });

  // Sort matches by start index
  matches.sort((a, b) => a.start - b.start);

  // Filter overlapping matches: keep the longest match at each position
  const filteredMatches = [];
  let currentEnd = 0;
  for (let i = 0; i < matches.length; i++) {
    const m = matches[i];
    if (m.start >= currentEnd) {
      filteredMatches.push(m);
      currentEnd = m.end;
    } else if (m.end > currentEnd) {
      // Overlapping but longer match - replace last
      filteredMatches[filteredMatches.length - 1] = m;
      currentEnd = m.end;
    }
  }

  // Build highlighted HTML string
  let result = '';
  let pos = 0;
  filteredMatches.forEach(({ start, end, className, text }) => {
    if (pos < start) {
      result += escapeHtml(text.slice ? text.slice(pos, start) : text.substring(pos, start)) || escapeHtml(text.substring(pos, start));
    }
    const tokenText = text.substring ? text.substring(start, end) : text.slice(start, end);
    const escapedToken = escapeHtml(text.substring ? text.substring(start, end) : text.slice(start, end));
    result += `<span class="${className}">${escapedToken}</span>`;
    pos = end;
  });
  if (pos < textLength) {
    result += escapeHtml(text.substring(pos));
  }

  return result;
}

// Component for the query editor with theme-aware syntax highlighting and modern UI
export default function ThemeSyntaxHighlighting({ query, onChange, placeholder }) {
  const theme = useContext(ThemeContext);

  // Memoize highlighted HTML to avoid unnecessary recalculations
  const highlightedHtml = useMemo(() => {
    if (!query) return '';
    return applySyntaxHighlighting(query);
  }, [query]);

  // Theme styles for light and dark modes
  const themeStyles = {
    light: {
      backgroundColor: '#fff',
      color: '#222',
      borderColor: '#ccc',
      caretColor: '#000',
      keyword: '#0077cc',
      string: '#d14',
      number: '#099',
      comment: '#998',
      operator: '#333',
      identifier: '#333',
      placeholder: '#999',
      fontFamily: "'Fira Mono', monospace",
    },
    dark: {
      backgroundColor: '#1e1e1e',
      color: '#d4d4d4',
      borderColor: '#333',
      caretColor: '#fff',
      keyword: '#569cd6',
      string: '#d69d85',
      number: '#b5cea8',
      comment: '#6a9955',
      operator: '#d4d4d4',
      identifier: '#d4d4d4',
      placeholder: '#555',
      fontFamily: "'Fira Mono', monospace",
    },
  };

  const styles = themeStyles[theme] || themeStyles.light;

  // Controlled textarea input handler
  function handleInput(e) {
    onChange(e.target.value);
  }

  return (
    <>
      <style>{`
        .query-editor-container {
          position: relative;
          width: 100%;
          max-width: 100%;
          font-family: ${styles.fontFamily};
          font-size: 14px;
          line-height: 1.5;
          border: 1px solid ${styles.borderColor};
          border-radius: 6px;
          background-color: ${styles.backgroundColor};
          color: ${styles.color};
          box-sizing: border-box;
          overflow: hidden;
          box-shadow: 0 2px 8px rgba(0,0,0,0.1);
          transition: background-color 0.3s ease, color 0.3s ease, border-color 0.3s ease;
        }
        .query-editor-textarea,
        .query-editor-highlight {
          font-family: inherit;
          font-size: inherit;
          line-height: inherit;
          padding: 12px 16px;
          white-space: pre-wrap;
          word-wrap: break-word;
          overflow-wrap: break-word;
          outline: none;
          border: none;
          margin: 0;
          box-sizing: border-box;
          width: 100%;
          min-height: 150px;
          border-radius: 6px;
        }
        .query-editor-textarea {
          position: relative;
          background: transparent;
          color: transparent;
          caret-color: ${styles.caretColor};
          resize: vertical;
          z-index: 2;
        }
        .query-editor-textarea::selection {
          background: rgba(100, 150, 250, 0.3);
        }
        .query-editor-highlight {
          position: absolute;
          top: 0;
          left: 0;
          pointer-events: none;
          z-index: 1;
          user-select: none;
          color: ${styles.color};
        }
        .query-editor-container:focus-within {
          border-color: ${styles.keyword};
          box-shadow: 0 0 8px ${styles.keyword}80;
        }
        .query-editor-textarea::placeholder {
          color: ${styles.placeholder};
        }

        /* Syntax Highlighting */
        .keyword {
          color: ${styles.keyword};
          font-weight: 600;
        }
        .string {
          color: ${styles.string};
        }
        .number {
          color: ${styles.number};
        }
        .comment {
          color: ${styles.comment};
          font-style: italic;
        }
        .operator {
          color: ${styles.operator};
          font-weight: 600;
        }
        .identifier {
          color: ${styles.identifier};
        }
      `}</style>
      <div className="query-editor-container" aria-label="Query editor">
        <pre
          aria-hidden="true"
          className="query-editor-highlight"
          dangerouslySetInnerHTML={{ __html: highlightedHtml + '\n' }}
        />
        <textarea
          className="query-editor-textarea"
          spellCheck="false"
          value={query}
          onChange={handleInput}
          placeholder={placeholder || 'Write your query here...'}
          aria-multiline="true"
          rows={8}
        />

